import {prepareColor,renderColor,nativeColorMask,detectPrint} from './color-scene-engine.js';
let context;
self.onmessage=({data:{id,input}})=>{try{let result;if(input.kind==='prepare'){context=prepareColor(input);result={ready:true};}else if(input.kind==='mask')result={values:nativeColorMask(input.result,input.data,input.width,input.height)};else if(input.kind==='ink')result={values:detectPrint(input.data,input.width,input.height,input.mask,input.rect,input.params)};else if(input.kind==='render'){if(!context)throw Error('Prepare color pixels first.');result=renderColor(context,input.params);}else throw Error('Unknown color job.');const transfers=[];if(result.data)transfers.push(result.data.buffer);if(result.values)transfers.push(result.values.buffer);self.postMessage({id,result},transfers);}catch(e){self.postMessage({id,error:e.message});}};
